//! Lowers the typed tree to register bytecode ([`crate::vm::Insn`]).
//!
//! Locals live in the first registers of a frame; expression temporaries are allocated above
//! them with a stack discipline. Each instruction records the source offset Elasticsearch's
//! generated bytecode would attribute it to: nodes that write debug info there (calls, field
//! loads, arithmetic, casts, …) update a "current location" before their operands are compiled,
//! exactly like the JVM line number table, so a runtime error points where Elasticsearch points.
//!
//! The compiler also tracks the JVM local-variable slot every variable would occupy (`this`, the
//! loop counter, then locals in declaration order with `long`/`double` taking two slots and
//! sibling blocks reusing slots) because helpful `NullPointerException` messages name them
//! (`because "<local2>" is null`).

use std::sync::Arc;

use crate::analyze::Analyzed;
use crate::ast::Op;
use crate::func::RefSpec;
use crate::ir::*;
use crate::lookup::{Registry, MethodKind};
use crate::types::Ty;
use crate::vm::{BitOp, CmpOp, ConstVal, DocWhat, Function, Handler, Insn, ProgConst, Program, Reg};

pub struct Options {
    pub max_loop_counter: u32,
    pub regex_limit_factor: i32,
    /// `script.painless.max_allocation_bytes` of the script's context (0: not tracked).
    pub max_allocation_bytes: u64,
}

#[derive(Default)]
struct Pool {
    consts: Vec<ConstVal>,
    casts: Vec<Cast>,
    types: Vec<Ty>,
    names: Vec<Box<str>>,
    defops: Vec<DefOp>,
    refs: Vec<RefSpec>,
    doc_fields: Vec<Box<str>>,
    dyn_sites: u32,
    map_sites: u32,
    /// Static argument types and result type of each `def` call site.
    dyn_sigs: Vec<(Vec<Ty>, Ty)>,
    /// Allocations are charged against `max_allocation_bytes`.
    alloc: bool,
    /// Per string concatenation: the bytes its primitive operands and the result charge, and
    /// which operands are references (charged by their length at run time).
    concat_infos: Vec<(u64, Vec<bool>)>,
}

impl Pool {
    fn konst(&mut self, k: ConstVal) -> u32 {
        // strings are deduplicated so equal literals are the same object (`'a' === 'a'`)
        if let ConstVal::Str(s) = &k
            && let Some(i) = self.consts.iter().position(|c| matches!(c, ConstVal::Str(x) if x == s)) {
                return i as u32;
            }
        self.consts.push(k);
        (self.consts.len() - 1) as u32
    }
    fn cast(&mut self, c: Cast) -> u32 {
        if let Some(i) = self.casts.iter().position(|x| *x == c) {
            return i as u32;
        }
        self.casts.push(c);
        (self.casts.len() - 1) as u32
    }
    fn ty(&mut self, t: Ty) -> u32 {
        if let Some(i) = self.types.iter().position(|x| *x == t) {
            return i as u32;
        }
        self.types.push(t);
        (self.types.len() - 1) as u32
    }
    fn name(&mut self, n: &str) -> u32 {
        if let Some(i) = self.names.iter().position(|x| &**x == n) {
            return i as u32;
        }
        self.names.push(n.into());
        (self.names.len() - 1) as u32
    }
    fn defop(&mut self, d: DefOp) -> u32 {
        self.defops.push(d);
        (self.defops.len() - 1) as u32
    }
    fn doc_field(&mut self, n: &str) -> u32 {
        if let Some(i) = self.doc_fields.iter().position(|x| &**x == n) {
            return i as u32;
        }
        self.doc_fields.push(n.into());
        (self.doc_fields.len() - 1) as u32
    }
}

/// The JVM frame layout of `execute` Elasticsearch generates (helpful NPE messages name slots):
/// `this`, the execute method's parameters, the loop counter, slots doc-based script classes
/// reserve, then the context getters the script uses.
#[derive(Clone, Default)]
pub struct ExecLayout {
    /// Context variables that are parameters of `execute` (`explanation` of score scripts).
    pub params: Vec<u32>,
    /// Slots between the loop counter and the first getter local.
    pub reserved: u16,
}

pub fn compile(
    a: Analyzed,
    source: Arc<str>,
    reg: &Registry,
    opts: &Options,
    ctx_vars: usize,
    doc_var: Option<u32>,
    layout: &ExecLayout,
) -> Result<Program, crate::error::CompileError> {
    let mut pool = Pool { alloc: opts.max_allocation_bytes > 0, ..Pool::default() };
    let mut functions = Vec::with_capacity(a.functions.len());
    for (i, f) in a.functions.iter().enumerate() {
        let is_exec = i as u32 == a.execute;
        let captures = a.lambda_captures.get(&(i as u32)).cloned().unwrap_or_default();
        let fc = Fc::new(reg, &mut pool, f, captures, is_exec, &a.used_vars, ctx_vars, doc_var, layout);
        functions.push(fc.run());
    }
    let mut patterns = Vec::with_capacity(a.patterns.len());
    for pc in &a.patterns {
        patterns.push(match pc {
            crate::analyze::PatternConst::Regex(p, flags) => {
                let mut fl = 0;
                for c in flags.chars() {
                    fl |= crate::regex::flag_of(c).unwrap_or(0);
                }
                let r = crate::regex::Regex::compile(p, fl).map_err(|e| crate::error::CompileError::illegal_argument(0, e.description))?;
                ProgConst::Regex(Arc::new(r))
            }
            crate::analyze::PatternConst::Extractor(x) => ProgConst::Extractor(x.clone()),
        });
    }
    Ok(Program {
        source,
        functions,
        consts: pool.consts,
        casts: pool.casts,
        types: pool.types,
        names: pool.names,
        def_links: pool.defops.iter().map(|_| std::sync::atomic::AtomicU64::new(0)).collect(),
        fast_ran: std::sync::atomic::AtomicBool::new(false),
        defops: pool.defops,
        funcrefs: pool.refs,
        patterns,
        doc_fields: pool.doc_fields,
        execute: a.execute,
        statements: a.statements,
        used_vars: a.used_vars,
        bindings: a.bindings,
        dyn_sites: pool.dyn_sites,
        dyn_sigs: pool.dyn_sigs,
        map_sites: pool.map_sites,
        max_loop_counter: opts.max_loop_counter,
        regex_limit_factor: opts.regex_limit_factor,
        max_allocation_bytes: opts.max_allocation_bytes,
        concat_infos: pool.concat_infos,
        uses_score: a.uses_score,
    })
}

struct LoopCtx {
    breaks: Vec<usize>,
    continues: Vec<usize>,
}

struct Fc<'a> {
    reg: &'a Registry,
    pool: &'a mut Pool,
    f: &'a TFunction,
    code: Vec<Insn>,
    locs: Vec<u32>,
    cur: u32,
    next: u16,
    max: u16,
    loops: Vec<LoopCtx>,
    handlers: Vec<Handler>,
    captures: Vec<u32>,
    is_exec: bool,
    used_vars: &'a [bool],
    ctx_vars: usize,
    /// JVM slot of each analyzer slot (for NPE messages)
    jvm: Vec<u16>,
    /// 1-based method parameter index of each analyzer slot that is a parameter (the JVM names
    /// those `<parameterN>`), `u16::MAX` otherwise.
    jvm_param: Vec<u16>,
    layout: &'a ExecLayout,
    jvm_next: u16,
    null_descs: Vec<(u32, Box<str>)>,
    /// Slot of the context's `doc` variable in `execute`.
    doc_var: Option<u32>,
    /// Location a no-op cast wrote when no instruction has been emitted since. The JVM resolves
    /// an instruction's line to the *first* line-number entry at its offset, so a store that
    /// writes its own entry right after such a cast (no bytecode in between) reports the cast's.
    shadow: Option<u32>,
}

/// `AllocSizes.pad8`.
fn pad8(b: u64) -> u64 {
    b.saturating_add(7) & !7
}

/// `AllocSizes.fieldSize`: bytes of one element (references count 8).
fn field_bytes(t: Ty) -> u64 {
    if t.dims > 0 {
        return 8;
    }
    match t {
        Ty::LONG | Ty::DOUBLE => 8,
        Ty::INT | Ty::FLOAT => 4,
        Ty::SHORT | Ty::CHAR => 2,
        Ty::BYTE | Ty::BOOLEAN => 1,
        _ => 8,
    }
}

/// `AllocSizes.stringConcatPrimitiveBytes`: the longest rendering of a primitive, in UTF-16.
fn concat_bytes(p: crate::ir::Prim) -> u64 {
    use crate::ir::Prim;
    match p {
        Prim::Bool => 10,
        Prim::Byte => 8,
        Prim::Short => 12,
        Prim::Char => 2,
        Prim::Int => 22,
        Prim::Long => 40,
        Prim::Float => 32,
        Prim::Double => 48,
    }
}

fn is_wide(t: Ty) -> bool {
    t == Ty::LONG || t == Ty::DOUBLE
}

impl<'a> Fc<'a> {
    #[allow(clippy::too_many_arguments)]
    fn new(
        reg: &'a Registry,
        pool: &'a mut Pool,
        f: &'a TFunction,
        captures: Vec<u32>,
        is_exec: bool,
        used_vars: &'a [bool],
        ctx_vars: usize,
        doc_var: Option<u32>,
        layout: &'a ExecLayout,
    ) -> Fc<'a> {
        let n = f.nlocals as u16;
        Fc {
            reg,
            pool,
            f,
            code: Vec::new(),
            locs: Vec::new(),
            // no line number written yet: an error before the first one has no position
            cur: u32::MAX,
            next: n,
            max: n,
            loops: Vec::new(),
            handlers: Vec::new(),
            captures,
            is_exec,
            used_vars,
            ctx_vars,
            jvm: vec![u16::MAX; f.nlocals as usize],
            jvm_param: vec![u16::MAX; f.nlocals as usize],
            layout,
            jvm_next: 0,
            null_descs: Vec::new(),
            doc_var: if is_exec { doc_var } else { None },
            shadow: None,
        }
    }

    fn run(mut self) -> Function {
        // JVM slots: `this` for execute and script functions (lambdas are static), parameters
        // (captures first for lambdas), then the loop counter
        let is_lambda = self.f.name.starts_with("lambda$");
        if !is_lambda {
            self.jvm_next = 1;
        }
        let mut nparam = 0u16;
        if is_lambda {
            for &c in &self.captures.clone() {
                nparam += 1;
                self.param_slot(c, nparam);
            }
        }
        if self.is_exec {
            // execute's own parameters, the loop counter, reserved slots, then the context
            // getters the script uses
            for &i in &self.layout.params {
                nparam += 1;
                self.param_slot(i, nparam);
            }
            if self.f.loop_limit {
                self.jvm_next += 1;
            }
            self.jvm_next += self.layout.reserved;
            for i in 0..self.ctx_vars {
                if self.used_vars[i] && !self.layout.params.contains(&(i as u32)) {
                    self.jvm_slot(i as u32, self.f.local_tys[i]);
                }
            }
            for i in 0..self.ctx_vars {
                if self.used_vars[i] {
                    self.emit(Insn::LoadVar { d: i as Reg, var: i as u32 });
                }
            }
        } else {
            for i in 0..self.f.params.len() {
                nparam += 1;
                self.param_slot(i as u32, nparam);
            }
            if self.f.loop_limit {
                self.jvm_next += 1;
            }
        }
        let body = &self.f.body;
        self.stmts(body);
        // functions always end in a return (the analyzer adds one); guard anyway
        self.emit(Insn::RetVoid);
        let captures = self.captures.iter().map(|&c| c as Reg).collect();
        let mut func = Function {
            name: self.f.name.clone(),
            params: self.f.params.clone(),
            ret: self.f.ret,
            nregs: self.max.max(1),
            code: self.code,
            locs: self.locs,
            handlers: self.handlers,
            loop_limit: self.f.loop_limit,
            captures,
            loc: self.f.loc,
            null_descs: Vec::new(),
        };
        func.null_descs = self.null_descs;
        crate::peephole::optimize(&mut func);
        func
    }

    fn param_slot(&mut self, slot: u32, index: u16) {
        if let Some(p) = self.jvm_param.get_mut(slot as usize) {
            *p = index;
        }
        let ty = self.f.local_tys.get(slot as usize).copied().unwrap_or(Ty::DEF);
        self.jvm_slot(slot, ty);
    }

    fn jvm_slot(&mut self, slot: u32, ty: Ty) {
        if let Some(s) = self.jvm.get_mut(slot as usize) {
            *s = self.jvm_next;
        }
        self.jvm_next += if is_wide(ty) { 2 } else { 1 };
    }

    // ------------------------------------------------------------------ emission helpers

    fn emit(&mut self, i: Insn) -> usize {
        self.shadow = None;
        self.code.push(i);
        self.locs.push(self.cur);
        self.code.len() - 1
    }

    /// Emits a store whose node writes `ploc` after its value: see `shadow`.
    fn emit_store(&mut self, i: Insn, ploc: u32) -> usize {
        let at = self.shadow.take().unwrap_or(ploc);
        self.cur = at;
        let pc = self.emit(i);
        self.cur = ploc;
        pc
    }

    /// The `DefNorm` operand for an index of static type `t`: see [`Insn::DefNorm`].
    fn index_site(&mut self, t: Ty) -> u32 {
        if crate::dynamic::can_convert(self.reg, t, Ty::INT) {
            u32::MAX
        } else {
            self.pool.ty(t)
        }
    }

    fn here(&self) -> u32 {
        self.code.len() as u32
    }

    fn patch(&mut self, at: usize, target: u32) {
        match &mut self.code[at] {
            Insn::Jmp { t } | Insn::Jf { t, .. } | Insn::Jt { t, .. } | Insn::JNull { t, .. } | Insn::JNonNull { t, .. } | Insn::JCmpFalse { t, .. } | Insn::JCmp { t, .. } | Insn::IterNext { t, .. } => {
                *t = target
            }
            _ => panic!("patching a non-jump"),
        }
    }

    fn alloc(&mut self) -> Reg {
        let r = self.next;
        self.next += 1;
        if self.next > self.max {
            self.max = self.next;
        }
        r
    }

    fn alloc_n(&mut self, n: usize) -> Reg {
        let r = self.next;
        self.next += n as u16;
        if self.next > self.max {
            self.max = self.next;
        }
        r
    }

    fn mark(&self) -> u16 {
        self.next
    }

    fn release(&mut self, m: u16) {
        self.next = m;
    }

    fn konst(&mut self, d: Reg, k: &Const) {
        match k {
            Const::Bool(b) => {
                self.emit(Insn::Bool { d, v: *b });
            }
            Const::Int(v) => {
                self.emit(Insn::Int { d, v: *v });
            }
            Const::Long(v) => {
                let k = self.pool.konst(ConstVal::Long(*v));
                self.emit(Insn::Const { d, k });
            }
            Const::Float(v) => {
                let k = self.pool.konst(ConstVal::Float(*v));
                self.emit(Insn::Const { d, k });
            }
            Const::Double(v) => {
                let k = self.pool.konst(ConstVal::Double(*v));
                self.emit(Insn::Const { d, k });
            }
            Const::Str(s) => {
                let k = self.pool.konst(ConstVal::Str(s.clone()));
                self.emit(Insn::Const { d, k });
            }
            Const::Byte(v) => {
                let k = self.pool.konst(ConstVal::Byte(*v));
                self.emit(Insn::Const { d, k });
            }
            Const::Short(v) => {
                let k = self.pool.konst(ConstVal::Short(*v));
                self.emit(Insn::Const { d, k });
            }
            Const::Char(v) => {
                let k = self.pool.konst(ConstVal::Char(*v));
                self.emit(Insn::Const { d, k });
            }
        }
    }

    /// Records the helpful-NPE description of a receiver for the instruction about to be
    /// emitted.
    fn null_desc(&mut self, recv: &TExpr) {
        if let Some(d) = self.describe(recv) {
            let pc = self.code.len() as u32;
            self.null_descs.push((pc, d.into()));
        }
    }

    fn describe(&self, e: &TExpr) -> Option<String> {
        match &e.k {
            TK::Load(p) => match &**p {
                Place::Local { slot } => {
                    let j = *self.jvm.get(*slot as usize)?;
                    if let Some(&p) = self.jvm_param.get(*slot as usize)
                        && p != u16::MAX
                    {
                        Some(format!("\"<parameter{p}>\""))
                    } else if j == u16::MAX {
                        None
                    } else {
                        Some(format!("\"<local{j}>\""))
                    }
                }
                Place::Shortcut { getter: Some(g), .. } | Place::MapKey { getter: Some(g), .. } | Place::ListIdx { getter: Some(g), .. } => {
                    Some(format!("the return value of \"{}\"", crate::dynamic::method_descriptor(self.reg, *g)))
                }
                _ => None,
            },
            TK::Cast(inner, _) => self.describe(inner),
            TK::Invoke { m, .. } => Some(format!("the return value of \"{}\"", crate::dynamic::method_descriptor(self.reg, *m))),
            _ => None,
        }
    }

    // ------------------------------------------------------------------ statements

    fn stmts(&mut self, ss: &[TStmt]) {
        for s in ss {
            self.stmt(s);
        }
    }

    fn block_scope<F: FnOnce(&mut Self)>(&mut self, f: F) {
        let saved = self.jvm_next;
        f(self);
        self.jvm_next = saved;
    }

    fn stmt(&mut self, s: &TStmt) {
        let m = self.mark();
        match s {
            TStmt::Expr(e) => {
                self.effect(e);
            }
            TStmt::Decl { slot, ty, init, .. } => {
                let d = *slot as Reg;
                match init {
                    Some(x) => self.expr_to(x, d),
                    None => {
                        let k = crate::analyze::default_value(*ty, 0);
                        match k {
                            Some(TExpr { k: TK::Const(c), .. }) => self.konst(d, &c),
                            _ => {
                                self.emit(Insn::Null { d });
                            }
                        }
                    }
                }
                self.jvm_slot(*slot, *ty);
            }
            TStmt::If { c, then, els } => {
                let fj = self.jump_false(c);
                self.block_scope(|s| s.stmts(then));
                match els {
                    None => {
                        let h = self.here();
                        for j in fj {
                            self.patch(j, h);
                        }
                    }
                    Some(e) => {
                        let end = self.emit(Insn::Jmp { t: 0 });
                        let h = self.here();
                        for j in fj {
                            self.patch(j, h);
                        }
                        self.block_scope(|s| s.stmts(e));
                        let h = self.here();
                        self.patch(end, h);
                    }
                }
            }
            TStmt::While { c, body, loc } => {
                let saved = self.jvm_next;
                self.cond_loop(c.as_ref(), *loc, |s| s.stmts(body), |_| {});
                self.jvm_next = saved;
            }
            TStmt::DoWhile { c, body, loc } => {
                let saved = self.jvm_next;
                let start = self.here();
                self.loops.push(LoopCtx { breaks: Vec::new(), continues: Vec::new() });
                self.stmts(body);
                let lc = self.loops.pop().unwrap();
                let cont = self.here();
                match c {
                    Some(c) if self.f.loop_limit && fusable(c).is_some() => {
                        // condition, loop counter and back edge in one instruction
                        self.cur = c.loc;
                        let (op, a, b) = self.fused_operands(c);
                        self.cur = *loc;
                        self.emit(Insn::JCmp { op, a, b, t: start, lc: true });
                    }
                    _ => {
                        let fj = match c {
                            Some(c) => self.jump_false(c),
                            None => Vec::new(),
                        };
                        self.loop_check(*loc);
                        self.emit(Insn::Jmp { t: start });
                        let end = self.here();
                        for j in fj {
                            self.patch(j, end);
                        }
                    }
                }
                let end = self.here();
                for j in lc.breaks {
                    self.patch(j, end);
                }
                for j in lc.continues {
                    self.patch(j, cont);
                }
                self.jvm_next = saved;
            }
            TStmt::For { init, c, after, body, loc } => {
                let saved = self.jvm_next;
                for i in init {
                    self.stmt(i);
                }
                self.cond_loop(
                    c.as_ref(),
                    *loc,
                    |s| s.stmts(body),
                    |s| {
                        if let Some(a) = after {
                            let m2 = s.mark();
                            s.effect(a);
                            s.release(m2);
                        }
                    },
                );
                self.jvm_next = saved;
            }
            TStmt::EachArray { slot, iterable, cast, body, loc } | TStmt::EachIter { slot, iterable, cast, body, loc } => {
                let saved = self.jvm_next;
                let var_ty = self.f.local_tys[*slot as usize];
                self.jvm_slot(*slot, var_ty);
                // internal iterator (and array index) slots follow the variable
                let array = matches!(s, TStmt::EachArray { .. });
                self.jvm_next += if array { 2 } else { 1 };
                // a primitive variable over a `def` iterable converts like `ValueIterator`
                let vp = if !array && iterable.ty == Ty::DEF && var_ty.dims == 0 { Prim::of(var_ty).filter(|p| p.ty() == var_ty) } else { None };
                if !array && let Some((field, key_loc)) = self.doc_literal(iterable) {
                    // `for (x : doc['field'])`: an index loop over the doc values buffer, no
                    // `ScriptDocValues` or iterator per document
                    let fi = self.pool.doc_field(&field);
                    let n = self.alloc();
                    let i = self.alloc();
                    let tmp = self.alloc();
                    self.cur = key_loc;
                    self.emit(Insn::DocValue { d: n, field: fi, what: DocWhat::Fetch });
                    self.cur = iterable.loc;
                    self.emit(Insn::DocValue { d: n, field: fi, what: DocWhat::Size });
                    // the elements are read (and converted) at the loop, like an iterator's
                    self.cur = *loc;
                    self.emit(Insn::Int { d: i, v: 0 });
                    let start = self.here();
                    let exit = self.emit(Insn::JCmpFalse { op: CmpOp::LtI, a: i, b: n, t: 0 });
                    self.emit(Insn::DocAt { d: tmp, field: fi, i, p: vp.map_or(0, |p| p.index() + 1) });
                    self.emit(Insn::AddIK { d: i, a: i, k: 1 });
                    match if vp.is_some() { &None } else { cast } {
                        Some(c) => {
                            let ci = self.pool.cast(c.clone());
                            self.emit(cast_insn(*slot as Reg, tmp, ci, &self.pool.casts[ci as usize]));
                        }
                        None => {
                            self.emit(Insn::Mov { d: *slot as Reg, s: tmp });
                        }
                    }
                    self.loops.push(LoopCtx { breaks: Vec::new(), continues: Vec::new() });
                    self.stmts(body);
                    self.emit(Insn::Jmp { t: start });
                    let lc = self.loops.pop().unwrap();
                    let end = self.here();
                    self.patch(exit, end);
                    for j in lc.breaks {
                        self.patch(j, end);
                    }
                    for j in lc.continues {
                        self.patch(j, start);
                    }
                    self.jvm_next = saved;
                    return;
                }
                let it = self.alloc();
                let src = self.expr(iterable);
                self.emit(Insn::IterInit { d: it, s: src });
                let start = self.here();
                let tmp = self.alloc();
                let next = self.emit(Insn::IterNext { d: tmp, it, t: 0, p: vp.map_or(0, |p| p.index() + 1) });
                match if vp.is_some() { &None } else { cast } {
                    Some(c) => {
                        let ci = self.pool.cast(c.clone());
                        self.emit(cast_insn(*slot as Reg, tmp, ci, &self.pool.casts[ci as usize]));
                    }
                    None => {
                        self.emit(Insn::Mov { d: *slot as Reg, s: tmp });
                    }
                }
                self.loops.push(LoopCtx { breaks: Vec::new(), continues: Vec::new() });
                self.stmts(body);
                self.emit(Insn::Jmp { t: start });
                let lc = self.loops.pop().unwrap();
                let end = self.here();
                self.patch(next, end);
                for j in lc.breaks {
                    self.patch(j, end);
                }
                for j in lc.continues {
                    self.patch(j, start);
                }
                self.jvm_next = saved;
            }
            TStmt::Return(v, _) => match v {
                None => {
                    self.emit(Insn::RetVoid);
                }
                Some(x) => {
                    let r = self.expr(x);
                    self.emit(Insn::Ret { s: r });
                }
            },
            TStmt::Throw(x, _) => {
                let r = self.expr(x);
                self.emit(Insn::Throw { s: r });
            }
            TStmt::Break => {
                let j = self.emit(Insn::Jmp { t: 0 });
                if let Some(l) = self.loops.last_mut() {
                    l.breaks.push(j);
                }
            }
            TStmt::Continue => {
                let j = self.emit(Insn::Jmp { t: 0 });
                if let Some(l) = self.loops.last_mut() {
                    l.continues.push(j);
                }
            }
            TStmt::Try { body, catches } => {
                let start = self.here();
                self.block_scope(|s| s.stmts(body));
                let end = self.here();
                let mut ends = vec![self.emit(Insn::Jmp { t: 0 })];
                let mut hs = Vec::new();
                for c in catches {
                    let target = self.here();
                    hs.push(Handler { start, end, target, class: c.class, reg: c.slot as Reg });
                    let saved = self.jvm_next;
                    self.jvm_slot(c.slot, Ty::of(c.class));
                    self.stmts(&c.body);
                    self.jvm_next = saved;
                    ends.push(self.emit(Insn::Jmp { t: 0 }));
                }
                // inner handlers were pushed while compiling the body and are found first
                self.handlers.extend(hs);
                let h = self.here();
                for j in ends {
                    self.patch(j, h);
                }
            }
        }
        self.release(m);
    }

    /// A `while`/`for` loop. Elasticsearch lays it out as `cond; counter; body; after; goto`;
    /// we invert it (`goto cond; body; after; cond`) so an iteration takes one branch, and fold
    /// the loop counter into that branch when the condition is a primitive comparison. Source
    /// locations follow Elasticsearch's layout: the condition sees the location that preceded
    /// the loop, the body starts at the loop's own.
    fn cond_loop(&mut self, c: Option<&TExpr>, loc: u32, body: impl FnOnce(&mut Self), after: impl FnOnce(&mut Self)) {
        let pre = self.cur;
        let Some(c) = c else {
            let start = self.here();
            self.loop_check(loc);
            self.loops.push(LoopCtx { breaks: Vec::new(), continues: Vec::new() });
            body(self);
            let lc = self.loops.pop().unwrap();
            let cont = self.here();
            after(self);
            self.emit(Insn::Jmp { t: start });
            let end = self.here();
            for j in lc.breaks {
                self.patch(j, end);
            }
            for j in lc.continues {
                self.patch(j, cont);
            }
            return;
        };
        let fused = self.f.loop_limit && fusable(c).is_some();
        let entry = self.emit(Insn::Jmp { t: 0 });
        let body_start = self.here();
        if fused {
            self.cur = loc;
        } else {
            self.loop_check(loc);
        }
        self.loops.push(LoopCtx { breaks: Vec::new(), continues: Vec::new() });
        body(self);
        let lc = self.loops.pop().unwrap();
        let cont = self.here();
        after(self);
        let post = self.cur;
        let cond = self.here();
        self.patch(entry, cond);
        self.cur = pre;
        if fused {
            self.cur = c.loc;
            let m = self.mark();
            let (op, a, b) = self.fused_operands(c);
            self.release(m);
            self.cur = loc;
            self.emit(Insn::JCmp { op, a, b, t: body_start, lc: true });
        } else {
            for j in self.jump_true(c) {
                self.patch(j, body_start);
            }
        }
        self.cur = post;
        let end = self.here();
        for j in lc.breaks {
            self.patch(j, end);
        }
        for j in lc.continues {
            self.patch(j, cont);
        }
    }

    /// Operands of a condition [`fusable`] accepted.
    fn fused_operands(&mut self, c: &TExpr) -> (CmpOp, Reg, Reg) {
        let TK::Comp { l, r, .. } = &c.k else { unreachable!() };
        let op = fusable(c).unwrap();
        let (a, b) = self.operands(l, r);
        (op, a, b)
    }

    fn loop_check(&mut self, loc: u32) {
        if self.f.loop_limit {
            self.cur = loc;
            self.emit(Insn::LoopCheck);
        }
    }

    // ------------------------------------------------------------------ conditions

    /// Compiles a boolean expression as a branch: returns jumps to patch to the false target.
    fn jump_false(&mut self, c: &TExpr) -> Vec<usize> {
        match &c.k {
            TK::And(l, r) => {
                self.cur = c.loc;
                let mut j = self.jump_false(l);
                j.extend(self.jump_false(r));
                j
            }
            TK::Or(l, r) => {
                self.cur = c.loc;
                let tj = self.jump_true(l);
                let fj = self.jump_false(r);
                let h = self.here();
                for j in tj {
                    self.patch(j, h);
                }
                fj
            }
            TK::Unary { op: Op::Not, x, def: None } => {
                self.cur = c.loc;
                self.jump_true(x)
            }
            TK::Comp { op, l, r, operand } if cmp_op(*op, *operand).is_some() => {
                self.cur = c.loc;
                let cop = cmp_op(*op, *operand).unwrap();
                let m = self.mark();
                let (a, b) = self.operands(l, r);
                let j = self.emit(Insn::JCmpFalse { op: cop, a, b, t: 0 });
                self.release(m);
                vec![j]
            }
            _ => {
                let m = self.mark();
                let r = self.expr(c);
                let j = self.emit(Insn::Jf { c: r, t: 0 });
                self.release(m);
                vec![j]
            }
        }
    }

    fn jump_true(&mut self, c: &TExpr) -> Vec<usize> {
        match &c.k {
            TK::Or(l, r) => {
                self.cur = c.loc;
                let mut j = self.jump_true(l);
                j.extend(self.jump_true(r));
                j
            }
            TK::And(l, r) => {
                self.cur = c.loc;
                let fj = self.jump_false(l);
                let tj = self.jump_true(r);
                let h = self.here();
                for j in fj {
                    self.patch(j, h);
                }
                tj
            }
            TK::Unary { op: Op::Not, x, def: None } => {
                self.cur = c.loc;
                self.jump_false(x)
            }
            _ => {
                let m = self.mark();
                let r = self.expr(c);
                let j = self.emit(Insn::Jt { c: r, t: 0 });
                self.release(m);
                vec![j]
            }
        }
    }

    // ------------------------------------------------------------------ expressions

    /// Evaluates for side effects only.
    fn effect(&mut self, e: &TExpr) {
        let m = self.mark();
        match &e.k {
            TK::Assign { place, rhs, compound, post, ploc, .. } => {
                let d = self.alloc();
                self.assign(place, rhs, compound.as_deref(), *post, false, d, *ploc);
            }
            _ => {
                let d = self.alloc();
                self.expr_to(e, d);
            }
        }
        self.release(m);
    }

    /// Evaluates into some register (a local's own register for plain local reads).
    fn expr(&mut self, e: &TExpr) -> Reg {
        if let TK::Cast(x, Cast::Transparent) = &e.k {
            return self.expr(x);
        }
        if let TK::Load(p) = &e.k
            && let Place::Local { slot } = &**p {
                return *slot as Reg;
            }
        let d = self.alloc();
        self.expr_to(e, d);
        d
    }

    /// Evaluates two operands, copying the left one when the right one could change it.
    fn operands(&mut self, l: &TExpr, r: &TExpr) -> (Reg, Reg) {
        let a = match &l.k {
            TK::Load(p) if matches!(&**p, Place::Local { .. }) && mutates(r) => {
                let d = self.alloc();
                self.expr_to(l, d);
                d
            }
            _ => self.expr(l),
        };
        let b = self.expr(r);
        (a, b)
    }

    /// Boxing a primitive allocates its wrapper (`AllocSizes.boxSize`).
    fn charge_boxing(&mut self, from: Ty, to: Ty) {
        if self.pool.alloc && from.is_primitive() && from.dims == 0 && from != Ty::VOID && !to.is_primitive() {
            let bytes = if matches!(from, Ty::LONG | Ty::DOUBLE) { 24 } else { 16 };
            self.emit(Insn::Alloc { bytes });
        }
    }

    fn expr_to(&mut self, e: &TExpr, d: Reg) {
        match &e.k {
            TK::Const(k) => self.konst(d, k),
            TK::Null => {
                self.emit(Insn::Null { d });
            }
            TK::Cast(x, Cast::Transparent) => self.expr_to(x, d),
            TK::Cast(x, Cast::Noop) => {
                self.expr_to(x, d);
                self.cur = e.loc;
                // reference upcasts emit no bytecode; boxing calls `valueOf`
                if !x.ty.is_primitive() {
                    self.shadow = Some(e.loc);
                } else {
                    self.charge_boxing(x.ty, e.ty);
                }
            }
            TK::Cast(x, c) => {
                let m = self.mark();
                let s = self.expr(x);
                self.cur = e.loc;
                // unboxing a null names the null expression (helpful NPE)
                if matches!(c, Cast::Num { unbox: Some(_), .. } | Cast::Unbox(_)) {
                    self.null_desc(x);
                }
                self.charge_boxing(x.ty, e.ty);
                let ci = self.pool.cast(c.clone());
                self.emit(cast_insn(d, s, ci, &self.pool.casts[ci as usize]));
                self.release(m);
            }
            TK::Unary { op, x, def } => {
                self.cur = e.loc;
                let m = self.mark();
                let s = self.expr(x);
                match def {
                    Some(info) => {
                        let info = self.pool.defop(*info);
                        self.emit(Insn::DefUn { op: *op, d, s, info });
                    }
                    None => {
                        let t = x.ty;
                        let i = match (op, t) {
                            (Op::Sub, Ty::INT) => Insn::NegI { d, s },
                            (Op::Sub, Ty::LONG) => Insn::NegL { d, s },
                            (Op::Sub, Ty::FLOAT) => Insn::NegF { d, s },
                            (Op::Sub, Ty::DOUBLE) => Insn::NegD { d, s },
                            (Op::BwNot, Ty::INT) => Insn::NotI { d, s },
                            (Op::BwNot, Ty::LONG) => Insn::NotL { d, s },
                            (Op::Not, _) => Insn::Not { d, s },
                            _ => Insn::Mov { d, s },
                        };
                        self.emit(i);
                    }
                }
                self.release(m);
            }
            TK::Binary { op, l, r, operand, def } => {
                self.cur = e.loc;
                let m = self.mark();
                let (a, b) = self.operands(l, r);
                match def {
                    Some(info) => {
                        let info = self.pool.defop(*info);
                        self.emit(Insn::DefBin { op: *op, d, a, b, info });
                    }
                    None => {
                        let i = arith(*op, *operand, d, a, b);
                        self.emit(i);
                    }
                }
                self.release(m);
            }
            TK::Regex { find, l, r } => {
                self.cur = e.loc;
                let m = self.mark();
                // Elasticsearch evaluates the pattern first
                let p = self.expr(r);
                let s = self.expr(l);
                self.emit(Insn::RegexOp { find: *find, d, s, p });
                self.release(m);
            }
            TK::Concat(parts) => {
                self.cur = e.loc;
                let m = self.mark();
                let a = self.alloc_n(parts.len());
                for (i, p) in parts.iter().enumerate() {
                    self.expr_to(p, a + i as u16);
                }
                if self.pool.alloc {
                    // `AllocSizes`: the result's overhead, each primitive's longest rendering,
                    // each reference's length at run time
                    let mut fixed = 32u64;
                    let mut refs = Vec::with_capacity(parts.len());
                    for p in parts {
                        let prim = crate::ir::Prim::of(p.ty).filter(|_| p.ty.dims == 0 && p.ty.is_primitive());
                        refs.push(prim.is_none());
                        fixed += prim.map_or(0, concat_bytes);
                    }
                    self.pool.concat_infos.push((fixed, refs));
                    let info = (self.pool.concat_infos.len() - 1) as u32;
                    self.emit(Insn::AllocConcat { a, n: parts.len() as u16, info });
                }
                self.emit(Insn::Concat { d, a, n: parts.len() as u16 });
                self.release(m);
            }
            TK::Comp { op, l, r, operand } => {
                self.cur = e.loc;
                let m = self.mark();
                let (a, b) = self.operands(l, r);
                match cmp_op(*op, *operand) {
                    Some(cop) => {
                        self.emit(Insn::Cmp { op: cop, d, a, b });
                    }
                    None => {
                        let args = [crate::ir::SiteArg::of(l.ty), crate::ir::SiteArg::of(r.ty)];
                        let info = self.pool.defop(DefOp { ret: Ty::BOOLEAN, explicit: false, compound: false, args, site: [l.ty, r.ty] });
                        self.emit(Insn::DefCmp { op: *op, d, a, b, info });
                    }
                }
                self.release(m);
            }
            TK::And(..) | TK::Or(..) => {
                self.cur = e.loc;
                let fj = self.jump_false(e);
                self.emit(Insn::Bool { d, v: true });
                let end = self.emit(Insn::Jmp { t: 0 });
                let h = self.here();
                for j in fj {
                    self.patch(j, h);
                }
                self.emit(Insn::Bool { d, v: false });
                let h = self.here();
                self.patch(end, h);
            }
            TK::InstanceOf { x, ty, fixed } => {
                let m = self.mark();
                let s = self.expr(x);
                match fixed {
                    Some(b) => {
                        self.emit(Insn::Bool { d, v: *b });
                    }
                    None if *ty == Ty::DEF => {
                        self.emit(Insn::Bool { d, v: true });
                    }
                    None => {
                        let t = self.pool.ty(*ty);
                        self.emit(Insn::InstanceOf { d, s, ty: t });
                    }
                }
                self.release(m);
            }
            TK::Cond { c, t, f } => {
                self.cur = e.loc;
                let fj = self.jump_false(c);
                self.expr_to(t, d);
                let end = self.emit(Insn::Jmp { t: 0 });
                let h = self.here();
                for j in fj {
                    self.patch(j, h);
                }
                self.expr_to(f, d);
                let h = self.here();
                self.patch(end, h);
            }
            TK::Elvis { l, r } => {
                self.cur = e.loc;
                self.expr_to(l, d);
                let j = self.emit(Insn::JNonNull { s: d, t: 0 });
                self.expr_to(r, d);
                let h = self.here();
                self.patch(j, h);
            }
            TK::NewList(vs) => {
                self.cur = e.loc;
                let m = self.mark();
                let a = self.alloc_n(vs.len());
                for (i, v) in vs.iter().enumerate() {
                    self.expr_to(v, a + i as u16);
                }
                self.emit(Insn::NewList { d, a, n: vs.len() as u16 });
                self.release(m);
            }
            TK::NewMap(ps) => {
                self.cur = e.loc;
                let m = self.mark();
                let a = self.alloc_n(ps.len() * 2);
                for (i, (k, v)) in ps.iter().enumerate() {
                    self.expr_to(k, a + 2 * i as u16);
                    self.expr_to(v, a + 2 * i as u16 + 1);
                }
                self.emit(Insn::NewMap { d, a, n: ps.len() as u16 });
                self.release(m);
            }
            TK::NewArray { dims, aty } => {
                self.cur = e.loc;
                let m = self.mark();
                let a = self.alloc_n(dims.len());
                for (i, v) in dims.iter().enumerate() {
                    self.expr_to(v, a + i as u16);
                }
                if self.pool.alloc {
                    // the innermost elements of every level allocated up front
                    let mut inner = *aty;
                    for _ in 0..dims.len() {
                        inner = inner.component();
                    }
                    self.emit(Insn::AllocArray { a, n: dims.len() as u8, w: field_bytes(inner) as u8 });
                }
                let ty = self.pool.ty(*aty);
                self.emit(Insn::NewArray { d, ty, a, n: dims.len() as u8 });
                self.release(m);
            }
            TK::ArrayInit(vs, aty) => {
                self.cur = e.loc;
                let m = self.mark();
                if self.pool.alloc {
                    let bytes = pad8(16 + vs.len() as u64 * field_bytes(aty.component()));
                    self.emit(Insn::Alloc { bytes: bytes.min(u32::MAX as u64) as u32 });
                }
                let a = self.alloc_n(vs.len());
                for (i, v) in vs.iter().enumerate() {
                    self.expr_to(v, a + i as u16);
                }
                let ty = self.pool.ty(*aty);
                self.emit(Insn::ArrayInit { d, ty, a, n: vs.len() as u16 });
                self.release(m);
            }
            TK::New { ctor, args } => {
                self.cur = e.loc;
                let m = self.mark();
                let a = self.alloc_n(args.len());
                for (i, v) in args.iter().enumerate() {
                    self.expr_to(v, a + i as u16);
                }
                self.emit(Insn::Call { d, m: *ctor, a, n: args.len() as u8 });
                self.release(m);
            }
            TK::Invoke { recv, m: method, args, null_safe } => {
                let m = self.mark();
                match recv {
                    None => {
                        self.cur = e.loc;
                        let a = self.alloc_n(args.len());
                        for (i, v) in args.iter().enumerate() {
                            self.expr_to(v, a + i as u16);
                        }
                        self.emit(Insn::Call { d, m: *method, a, n: args.len() as u8 });
                    }
                    Some(r) => {
                        let a = self.alloc_n(args.len() + 1);
                        self.expr_to(r, a);
                        let mut skip = None;
                        if *null_safe {
                            self.cur = e.loc;
                            self.emit(Insn::Null { d });
                            skip = Some(self.emit(Insn::JNull { s: a, t: 0 }));
                        }
                        self.cur = e.loc;
                        for (i, v) in args.iter().enumerate() {
                            self.expr_to(v, a + 1 + i as u16);
                        }
                        self.null_desc(r);
                        let kind = self.reg.method(*method).kind;
                        if kind == MethodKind::Instance {
                            self.emit(Insn::CallRecv { d, m: *method, a, n: args.len() as u8 + 1 });
                        } else {
                            self.emit(Insn::Call { d, m: *method, a, n: args.len() as u8 + 1 });
                        }
                        if let Some(j) = skip {
                            let h = self.here();
                            self.patch(j, h);
                        }
                    }
                }
                self.release(m);
            }
            TK::InvokeDyn { recv, name, args, null_safe, result }
                if args.is_empty() && !*null_safe && matches!(&**name, "size" | "isEmpty") && self.doc_literal(recv).is_some() =>
            {
                // `doc['field'].size()` / `.isEmpty()` read the doc values buffer directly
                let (field, key_loc) = self.doc_literal(recv).unwrap();
                let fi = self.pool.doc_field(&field);
                self.cur = key_loc;
                self.emit(Insn::DocValue { d, field: fi, what: DocWhat::Fetch });
                self.cur = e.loc;
                let what = if &**name == "size" { DocWhat::Size } else { DocWhat::Empty };
                self.emit(Insn::DocValue { d, field: fi, what });
                if let Some(c) = result {
                    let ci = self.pool.cast(c.clone());
                    self.emit(cast_insn(d, d, ci, &self.pool.casts[ci as usize]));
                }
            }
            TK::InvokeDyn { recv, name, args, null_safe, result } => {
                let m = self.mark();
                let a = self.alloc_n(args.len() + 1);
                self.expr_to(recv, a);
                let mut skip = None;
                self.cur = e.loc;
                if *null_safe {
                    self.emit(Insn::Null { d });
                    skip = Some(self.emit(Insn::JNull { s: a, t: 0 }));
                }
                for (i, v) in args.iter().enumerate() {
                    self.expr_to(v, a + 1 + i as u16);
                }
                let name = self.pool.name(name);
                let site = self.pool.dyn_sites;
                self.pool.dyn_sites += 1;
                // the call site's static type, which `asType` converts the target method to
                let lambda = |x: &TExpr| matches!(x.k, TK::Lambda { .. } | TK::FuncRef(_));
                let arg_tys = args.iter().map(|x| if lambda(x) { Ty::DEF } else { x.ty }).collect();
                self.pool.dyn_sigs.push((arg_tys, if result.is_some() { e.ty } else { Ty::DEF }));
                let res = match result {
                    Some(c) => self.pool.cast(c.clone()),
                    None => u32::MAX,
                };
                self.emit(Insn::CallDyn { d, name, a, n: args.len() as u8 + 1, site, res });
                if let Some(j) = skip {
                    let h = self.here();
                    self.patch(j, h);
                }
                self.release(m);
            }
            TK::CallFunc { f, args } => {
                self.cur = e.loc;
                let m = self.mark();
                let a = self.alloc_n(args.len());
                for (i, v) in args.iter().enumerate() {
                    self.expr_to(v, a + i as u16);
                }
                self.emit(Insn::CallFunc { d, f: *f, a, n: args.len() as u8 });
                self.release(m);
            }
            TK::CallContext { m: method, args, binding } => {
                self.cur = e.loc;
                let m = self.mark();
                let a = self.alloc_n(args.len());
                // a class binding is constructed after its leading arguments: failures there
                // are located where the code stood after those
                let ctor_args = if binding.is_some() { crate::es::score::binding_ctor_args(&self.reg.method(*method).name, args.len()) } else { 0 };
                let mut ctor_loc = self.cur;
                for (i, v) in args.iter().enumerate() {
                    self.expr_to(v, a + i as u16);
                    if i + 1 == ctor_args {
                        ctor_loc = self.cur;
                    }
                }
                self.emit(Insn::CallCtx { d, m: *method, a, n: args.len() as u8, binding: binding.unwrap_or(u32::MAX), ctor_loc });
                self.release(m);
            }
            TK::Load(p) => self.load(p, e.loc, d),
            TK::Assign { place, rhs, compound, post, read, ploc } => {
                self.assign(place, rhs, compound.as_deref(), *post, *read, d, *ploc);
            }
            TK::Lambda { f, captures, iface } => {
                self.cur = e.loc;
                let m = self.mark();
                let a = self.alloc_n(captures.len());
                for (i, c) in captures.iter().enumerate() {
                    self.emit(Insn::Mov { d: a + i as u16, s: *c as Reg });
                }
                if self.pool.alloc && iface.is_some() {
                    // the capture object of a typed lambda
                    self.emit(Insn::Alloc { bytes: pad8(16 + 8 * captures.len() as u64) as u32 });
                }
                let iface = iface.map(|c| c.0 as u32).unwrap_or(u32::MAX);
                self.emit(Insn::Lambda { d, f: *f, a, n: captures.len() as u8, iface });
                self.release(m);
            }
            TK::FuncRef(spec) => {
                self.cur = e.loc;
                let (rs, cap) = crate::func::ref_spec(self.reg, spec);
                let idx = self.pool.refs.len() as u32;
                self.pool.refs.push(rs);
                let cap = match cap {
                    Some(slot) => slot as Reg,
                    None => Reg::MAX,
                };
                self.emit(Insn::FuncRef { d, spec: idx, cap });
            }
            TK::Pattern(p) => {
                self.emit(Insn::Pattern { d, p: *p });
            }
        }
    }

    fn load(&mut self, p: &Place, loc: u32, d: Reg) {
        let mk = self.mark();
        match p {
            Place::Local { slot } => {
                self.emit(Insn::Mov { d, s: *slot as Reg });
            }
            Place::DefDot { recv, name, null_safe, result } => {
                // `doc['field'].value` reads doc values directly
                if let Some((field, what, key_loc)) = self.doc_fast(recv, name) {
                    // the lookup fails at the key, reading the value at the dot
                    let fi = self.pool.doc_field(&field);
                    self.cur = key_loc;
                    self.emit(Insn::DocValue { d, field: fi, what: DocWhat::Fetch });
                    self.cur = loc;
                    self.emit(Insn::DocValue { d, field: fi, what });
                    if let Some(c) = result {
                        let ci = self.pool.cast(c.clone());
                        self.emit(cast_insn(d, d, ci, &self.pool.casts[ci as usize]));
                    }
                    self.release(mk);
                    return;
                }
                let r = self.expr(recv);
                self.cur = loc;
                let mut skip = None;
                if *null_safe {
                    self.emit(Insn::Null { d });
                    skip = Some(self.emit(Insn::JNull { s: r, t: 0 }));
                }
                let name = self.pool.name(name);
                let res = match result {
                    Some(c) => self.pool.cast(c.clone()),
                    None => u32::MAX,
                };
                self.emit(Insn::GetDot { d, r, name, res });
                if let Some(j) = skip {
                    let h = self.here();
                    self.patch(j, h);
                }
            }
            Place::StaticField { f } => {
                self.cur = loc;
                self.emit(Insn::StaticField { d, f: *f });
            }
            Place::Field { recv, f } => {
                let r = self.expr(recv);
                self.cur = loc;
                self.null_desc(recv);
                self.emit(Insn::Field { d, r, f: *f });
            }
            Place::Shortcut { recv, getter, .. } => {
                let a = self.alloc();
                self.expr_to(recv, a);
                self.cur = loc;
                self.null_desc(recv);
                self.emit(Insn::CallRecv { d, m: getter.expect("getter"), a, n: 1 });
            }
            Place::MapKey { recv, key, getter, .. } => {
                let m = getter.expect("getter");
                if let TK::Const(Const::Str(ks)) = &strip_noop(key).k
                    && self.reg.method(m).name.as_ref() == "get"
                    && self.reg.method(m).params.len() == 1
                {
                    // `params.x`, `map['key']`: a cached lookup with no argument shuffling
                    let r = self.expr(recv);
                    self.cur = loc;
                    // as compiling the key would: a no-op cast node moves the location
                    if let TK::Cast(_, Cast::Noop) = &key.k {
                        self.cur = key.loc;
                    }
                    let k = self.pool.konst(ConstVal::Str(ks.clone()));
                    let site = self.pool.map_sites;
                    self.pool.map_sites += 1;
                    self.null_desc(recv);
                    self.emit(Insn::MapGetK { d, r, k, m, site });
                    self.release(mk);
                    return;
                }
                let a = self.alloc_n(2);
                self.expr_to(recv, a);
                self.cur = loc;
                self.expr_to(key, a + 1);
                self.null_desc(recv);
                self.emit(Insn::CallRecv { d, m, a, n: 2 });
            }
            Place::ListIdx { recv, idx, getter, flip, .. } => {
                let a = self.alloc_n(2);
                self.expr_to(recv, a);
                self.expr_to(idx, a + 1);
                if *flip {
                    self.emit(Insn::Flip { d: a + 1, r: a, i: a + 1, list: true });
                }
                self.cur = loc;
                self.null_desc(recv);
                self.emit(Insn::CallRecv { d, m: getter.expect("getter"), a, n: 2 });
            }
            Place::ArrayIdx { recv, idx } => {
                let r = self.expr(recv);
                let i0 = self.expr(idx);
                let i = self.alloc();
                self.null_desc(recv);
                self.emit(Insn::Flip { d: i, r, i: i0, list: false });
                self.cur = loc;
                self.null_desc(recv);
                let ty = self.pool.ty(recv.ty);
                self.emit(Insn::ArrLoad { d, r, i, ty });
            }
            Place::ArrayLen { recv } => {
                let r = self.expr(recv);
                self.cur = loc;
                self.null_desc(recv);
                self.emit(Insn::ArrLen { d, r });
            }
            Place::DefIdx { recv, idx, result } => {
                // index normalization runs before Elasticsearch writes the brace's line number,
                // so its errors point at whatever wrote the last one
                let r = self.expr(recv);
                let i0 = self.expr(idx);
                let i = self.alloc();
                let t = self.index_site(idx.ty);
                self.emit(Insn::DefNorm { d: i, r, i: i0, t });
                self.cur = loc;
                let res = match result {
                    Some(c) => self.pool.cast(c.clone()),
                    None => u32::MAX,
                };
                self.emit(Insn::GetIdx { d, r, i, res });
            }
        }
        self.release(mk);
    }

    /// Recognizes `doc['literal'].value|.empty` and `doc['literal'].size()` over the context's
    /// `doc` variable.
    fn doc_fast(&self, recv: &TExpr, name: &str) -> Option<(String, DocWhat, u32)> {
        let what = match name {
            "value" => DocWhat::Value,
            "empty" => DocWhat::Empty,
            _ => return None,
        };
        let (field, loc) = self.doc_literal(recv)?;
        Some((field, what, loc))
    }

    /// `doc['literal']` over the context's `doc` variable: the field and the key's location.
    fn doc_literal(&self, recv: &TExpr) -> Option<(String, u32)> {
        if !self.is_exec {
            return None;
        }
        let TK::Load(p) = &recv.k else { return None };
        let Place::MapKey { recv: doc, key, .. } = &**p else { return None };
        let TK::Load(dp) = &doc.k else { return None };
        let Place::Local { slot } = &**dp else { return None };
        if Some(*slot) != self.doc_var {
            return None;
        }
        let key = strip_noop(key);
        let TK::Const(Const::Str(f)) = &key.k else { return None };
        Some((f.to_string(), key.loc))
    }

    #[allow(clippy::too_many_arguments)]
    fn assign(&mut self, place: &Place, rhs: &TExpr, compound: Option<&Compound>, post: bool, read: bool, d: Reg, ploc: u32) {
        let m = self.mark();
        match place {
            Place::Local { slot } => {
                let s = *slot as Reg;
                match compound {
                    None => {
                        self.expr_to(rhs, s);
                        if read {
                            self.emit(Insn::Mov { d, s });
                        }
                    }
                    Some(c) => {
                        if post && read {
                            self.emit(Insn::Mov { d, s });
                        }
                        // the operator node writes the store's location before its operands
                        self.cur = ploc;
                        let nv = self.compound_value(s, rhs, c, d);
                        self.emit(Insn::Mov { d: s, s: nv });
                        if read && !post {
                            self.emit(Insn::Mov { d, s });
                        }
                    }
                }
            }
            Place::DefDot { recv, name, .. } => {
                let r = self.alloc();
                self.expr_to(recv, r);
                let name_i = self.pool.name(name);
                match compound {
                    None => {
                        let v = self.alloc();
                        self.expr_to(rhs, v);
                        self.cur = ploc;
                        self.emit(Insn::SetDot { r, name: name_i, v });
                        if read {
                            self.emit(Insn::Mov { d, s: v });
                        }
                    }
                    Some(c) => {
                        let old = self.alloc();
                        self.cur = ploc;
                        self.emit(Insn::GetDot { d: old, r, name: name_i, res: u32::MAX });
                        if post && read {
                            self.emit(Insn::Mov { d, s: old });
                        }
                        let nv = self.compound_value(old, rhs, c, d);
                        self.emit(Insn::SetDot { r, name: name_i, v: nv });
                        if read && !post {
                            self.emit(Insn::Mov { d, s: nv });
                        }
                    }
                }
            }
            Place::Shortcut { recv, getter, setter } => {
                let a = self.alloc_n(2);
                self.expr_to(recv, a);
                match compound {
                    None => {
                        self.expr_to(rhs, a + 1);
                        if read {
                            self.emit(Insn::Mov { d, s: a + 1 });
                        }
                    }
                    Some(c) => {
                        let ga = self.alloc();
                        self.emit(Insn::Mov { d: ga, s: a });
                        let old = self.alloc();
                        self.null_desc(recv);
                        self.emit(Insn::CallRecv { d: old, m: getter.expect("getter"), a: ga, n: 1 });
                        if post && read {
                            self.emit(Insn::Mov { d, s: old });
                        }
                        let nv = self.compound_value(old, rhs, c, d);
                        self.emit(Insn::Mov { d: a + 1, s: nv });
                        if read && !post {
                            self.emit(Insn::Mov { d, s: nv });
                        }
                    }
                }
                let tmp = self.alloc();
                self.null_desc(recv);
                self.emit_store(Insn::CallRecv { d: tmp, m: setter.expect("setter"), a, n: 2 }, ploc);
            }
            Place::MapKey { recv, key, getter, setter } => {
                let a = self.alloc_n(3);
                self.expr_to(recv, a);
                self.expr_to(key, a + 1);
                match compound {
                    None => {
                        self.expr_to(rhs, a + 2);
                        if read {
                            self.emit(Insn::Mov { d, s: a + 2 });
                        }
                    }
                    Some(c) => {
                        let ga = self.alloc_n(2);
                        self.emit(Insn::Mov { d: ga, s: a });
                        self.emit(Insn::Mov { d: ga + 1, s: a + 1 });
                        let old = self.alloc();
                        self.null_desc(recv);
                        self.emit(Insn::CallRecv { d: old, m: getter.expect("getter"), a: ga, n: 2 });
                        if post && read {
                            self.emit(Insn::Mov { d, s: old });
                        }
                        let nv = self.compound_value(old, rhs, c, d);
                        self.emit(Insn::Mov { d: a + 2, s: nv });
                        if read && !post {
                            self.emit(Insn::Mov { d, s: nv });
                        }
                    }
                }
                let tmp = self.alloc();
                self.null_desc(recv);
                self.emit_store(Insn::CallRecv { d: tmp, m: setter.expect("setter"), a, n: 3 }, ploc);
            }
            Place::ListIdx { recv, idx, getter, setter, flip } => {
                let a = self.alloc_n(3);
                self.expr_to(recv, a);
                self.expr_to(idx, a + 1);
                if *flip {
                    self.emit(Insn::Flip { d: a + 1, r: a, i: a + 1, list: true });
                }
                match compound {
                    None => {
                        self.expr_to(rhs, a + 2);
                        if read {
                            self.emit(Insn::Mov { d, s: a + 2 });
                        }
                    }
                    Some(c) => {
                        let ga = self.alloc_n(2);
                        self.emit(Insn::Mov { d: ga, s: a });
                        self.emit(Insn::Mov { d: ga + 1, s: a + 1 });
                        let old = self.alloc();
                        self.null_desc(recv);
                        self.emit(Insn::CallRecv { d: old, m: getter.expect("getter"), a: ga, n: 2 });
                        if post && read {
                            self.emit(Insn::Mov { d, s: old });
                        }
                        let nv = self.compound_value(old, rhs, c, d);
                        self.emit(Insn::Mov { d: a + 2, s: nv });
                        if read && !post {
                            self.emit(Insn::Mov { d, s: nv });
                        }
                    }
                }
                let tmp = self.alloc();
                self.null_desc(recv);
                self.emit_store(Insn::CallRecv { d: tmp, m: setter.expect("setter"), a, n: 3 }, ploc);
            }
            Place::ArrayIdx { recv, idx } => {
                let r = self.alloc();
                self.expr_to(recv, r);
                let i = self.alloc();
                self.expr_to(idx, i);
                self.emit(Insn::Flip { d: i, r, i, list: false });
                match compound {
                    None => {
                        let v = self.alloc();
                        self.expr_to(rhs, v);
                        self.null_desc(recv);
                        let ty = self.pool.ty(recv.ty);
                        if read {
                            // Elasticsearch duplicates the value first
                            self.shadow = None;
                        }
                        self.emit_store(Insn::ArrStore { r, i, v, ty }, ploc);
                        if read {
                            self.emit(Insn::Mov { d, s: v });
                        }
                    }
                    Some(c) => {
                        let old = self.alloc();
                        self.null_desc(recv);
                        let ty = self.pool.ty(recv.ty);
                        self.emit(Insn::ArrLoad { d: old, r, i, ty });
                        if post && read {
                            self.emit(Insn::Mov { d, s: old });
                        }
                        let nv = self.compound_value(old, rhs, c, d);
                        self.null_desc(recv);
                        let ty = self.pool.ty(recv.ty);
                        self.emit(Insn::ArrStore { r, i, v: nv, ty });
                        if read && !post {
                            self.emit(Insn::Mov { d, s: nv });
                        }
                    }
                }
            }
            Place::DefIdx { recv, idx, .. } => {
                let r = self.alloc();
                self.expr_to(recv, r);
                let i = self.alloc();
                self.expr_to(idx, i);
                let t = self.index_site(idx.ty);
                self.emit(Insn::DefNorm { d: i, r, i, t });
                match compound {
                    None => {
                        let v = self.alloc();
                        self.expr_to(rhs, v);
                        self.cur = ploc;
                        let vty = if rhs.ty.is_primitive() { self.pool.ty(rhs.ty) } else { u32::MAX };
                        self.emit(Insn::SetIdx { r, i, v, vty });
                        if read {
                            self.emit(Insn::Mov { d, s: v });
                        }
                    }
                    Some(c) => {
                        let old = self.alloc();
                        self.emit(Insn::GetIdx { d: old, r, i, res: u32::MAX });
                        if post && read {
                            self.emit(Insn::Mov { d, s: old });
                        }
                        let nv = self.compound_value(old, rhs, c, d);
                        self.cur = ploc;
                        self.emit(Insn::SetIdx { r, i, v: nv, vty: u32::MAX });
                        if read && !post {
                            self.emit(Insn::Mov { d, s: nv });
                        }
                    }
                }
            }
            Place::StaticField { .. } | Place::Field { .. } | Place::ArrayLen { .. } => {
                // the analyzer rejects writes to these
                self.emit(Insn::Null { d });
            }
        }
        self.release(m);
    }

    /// Computes the new value of a compound assignment from the old value in `old`; returns
    /// the register holding it (already converted back to the left type).
    fn compound_value(&mut self, old: Reg, rhs: &TExpr, c: &Compound, avoid: Reg) -> Reg {
        let _ = avoid;
        let x = self.alloc();
        match &c.up {
            Some(cast) => {
                let ci = self.pool.cast(cast.clone());
                self.emit(cast_insn(x, old, ci, &self.pool.casts[ci as usize]));
            }
            None => {
                self.emit(Insn::Mov { d: x, s: old });
            }
        }
        let y = self.expr(rhs);
        let res = self.alloc();
        if c.concat {
            let a = self.alloc_n(2);
            self.emit(Insn::Mov { d: a, s: x });
            self.emit(Insn::Mov { d: a + 1, s: y });
            self.emit(Insn::Concat { d: res, a, n: 2 });
        } else if c.ty == Ty::DEF {
            // a compound assignment's operator call site takes both operands as `Object`
            let args = [crate::ir::SiteArg::Object, crate::ir::SiteArg::Object];
            let info = self.pool.defop(DefOp { ret: Ty::DEF, explicit: false, compound: true, args, site: [Ty::DEF, Ty::DEF] });
            self.emit(Insn::DefBin { op: c.op, d: res, a: x, b: y, info });
        } else {
            let i = arith(c.op, c.ty, res, x, y);
            self.emit(i);
        }
        if let Some(cast) = &c.down {
            let ci = self.pool.cast(cast.clone());
            self.emit(cast_insn(res, res, ci, &self.pool.casts[ci as usize]));
        }
        res
    }
}

/// A loop condition that compiles to one compare-and-branch which cannot throw.
fn fusable(c: &TExpr) -> Option<CmpOp> {
    let TK::Comp { op, operand, .. } = &c.k else { return None };
    if !matches!(*operand, Ty::INT | Ty::LONG | Ty::FLOAT | Ty::DOUBLE | Ty::BOOLEAN) {
        return None;
    }
    cmp_op(*op, *operand)
}

/// The expression under no-op conversions.
fn strip_noop(e: &TExpr) -> &TExpr {
    match &e.k {
        TK::Cast(x, Cast::Noop | Cast::Transparent) => strip_noop(x),
        _ => e,
    }
}

/// Whether evaluating `e` can assign a local variable.
fn mutates(e: &TExpr) -> bool {
    match &e.k {
        TK::Assign { .. } => true,
        TK::Const(_) | TK::Null | TK::Pattern(_) | TK::FuncRef(_) | TK::Lambda { .. } => false,
        TK::Load(p) => match &**p {
            Place::Local { .. } | Place::StaticField { .. } => false,
            Place::DefDot { recv, .. } | Place::Field { recv, .. } | Place::Shortcut { recv, .. } | Place::ArrayLen { recv } => mutates(recv),
            Place::MapKey { recv, key, .. } => mutates(recv) || mutates(key),
            Place::ListIdx { recv, idx, .. } | Place::ArrayIdx { recv, idx } | Place::DefIdx { recv, idx, .. } => mutates(recv) || mutates(idx),
        },
        TK::Cast(x, _) | TK::Unary { x, .. } | TK::InstanceOf { x, .. } => mutates(x),
        TK::Binary { l, r, .. } | TK::Comp { l, r, .. } | TK::Regex { l, r, .. } | TK::And(l, r) | TK::Or(l, r) | TK::Elvis { l, r } => mutates(l) || mutates(r),
        TK::Cond { c, t, f } => mutates(c) || mutates(t) || mutates(f),
        TK::Concat(v) | TK::NewList(v) | TK::ArrayInit(v, _) => v.iter().any(mutates),
        TK::NewArray { dims, .. } => dims.iter().any(mutates),
        TK::NewMap(v) => v.iter().any(|(k, x)| mutates(k) || mutates(x)),
        TK::New { args, .. } | TK::CallFunc { args, .. } | TK::CallContext { args, .. } => args.iter().any(mutates),
        TK::Invoke { recv, args, .. } => recv.as_ref().is_some_and(|r| mutates(r)) || args.iter().any(mutates),
        TK::InvokeDyn { recv, args, .. } => mutates(recv) || args.iter().any(mutates),
    }
}

fn cmp_op(op: Op, t: Ty) -> Option<CmpOp> {
    use CmpOp::*;
    Some(match (t, op) {
        (Ty::INT, Op::Eq | Op::Eqr) => EqI,
        (Ty::INT, Op::Ne | Op::Ner) => NeI,
        (Ty::INT, Op::Lt) => LtI,
        (Ty::INT, Op::Lte) => LeI,
        (Ty::INT, Op::Gt) => GtI,
        (Ty::INT, Op::Gte) => GeI,
        (Ty::LONG, Op::Eq | Op::Eqr) => EqL,
        (Ty::LONG, Op::Ne | Op::Ner) => NeL,
        (Ty::LONG, Op::Lt) => LtL,
        (Ty::LONG, Op::Lte) => LeL,
        (Ty::LONG, Op::Gt) => GtL,
        (Ty::LONG, Op::Gte) => GeL,
        (Ty::FLOAT, Op::Eq | Op::Eqr) => EqF,
        (Ty::FLOAT, Op::Ne | Op::Ner) => NeF,
        (Ty::FLOAT, Op::Lt) => LtF,
        (Ty::FLOAT, Op::Lte) => LeF,
        (Ty::FLOAT, Op::Gt) => GtF,
        (Ty::FLOAT, Op::Gte) => GeF,
        (Ty::DOUBLE, Op::Eq | Op::Eqr) => EqD,
        (Ty::DOUBLE, Op::Ne | Op::Ner) => NeD,
        (Ty::DOUBLE, Op::Lt) => LtD,
        (Ty::DOUBLE, Op::Lte) => LeD,
        (Ty::DOUBLE, Op::Gt) => GtD,
        (Ty::DOUBLE, Op::Gte) => GeD,
        (Ty::BOOLEAN, Op::Eq | Op::Eqr) => EqZ,
        (Ty::BOOLEAN, Op::Ne | Op::Ner) => NeZ,
        (Ty::DEF, Op::Eqr) => EqRef,
        (Ty::DEF, Op::Ner) => NeRef,
        (Ty::DEF, _) => return None,
        (_, Op::Eq) => EqObj,
        (_, Op::Ne) => NeObj,
        (_, Op::Eqr) => EqRef,
        (_, Op::Ner) => NeRef,
        _ => return None,
    })
}

/// The instruction for a conversion: the common widening conversions to `double`, `long` and
/// `int` get their own opcodes (one dispatch, no look at the cast description) and fall back to
/// the generic [`Insn::Cast`] for every other input.
fn cast_insn(d: Reg, s: Reg, c: u32, cast: &Cast) -> Insn {
    use crate::ir::Prim;
    match *cast {
        Cast::Num { to: Prim::Double, .. } | Cast::DefTo { to: Prim::Double, boxed: false, .. } | Cast::AsType(Ty::DOUBLE) => Insn::ToD { d, s, c },
        Cast::Num { to: Prim::Long, .. } | Cast::DefTo { to: Prim::Long, boxed: false, .. } | Cast::AsType(Ty::LONG) => Insn::ToL { d, s, c },
        Cast::Num { to: Prim::Int, .. } | Cast::DefTo { to: Prim::Int, boxed: false, .. } | Cast::AsType(Ty::INT) | Cast::MathResult { to: Ty::INT, .. } => Insn::ToI { d, s, c },
        _ => Insn::Cast { d, s, c },
    }
}

fn arith(op: Op, t: Ty, d: Reg, a: Reg, b: Reg) -> Insn {
    use Insn::*;
    match (t, op) {
        (Ty::INT, Op::Add) => AddI { d, a, b },
        (Ty::INT, Op::Sub) => SubI { d, a, b },
        (Ty::INT, Op::Mul) => MulI { d, a, b },
        (Ty::INT, Op::Div) => DivI { d, a, b },
        (Ty::INT, Op::Rem) => RemI { d, a, b },
        (Ty::LONG, Op::Add) => AddL { d, a, b },
        (Ty::LONG, Op::Sub) => SubL { d, a, b },
        (Ty::LONG, Op::Mul) => MulL { d, a, b },
        (Ty::LONG, Op::Div) => DivL { d, a, b },
        (Ty::LONG, Op::Rem) => RemL { d, a, b },
        (Ty::FLOAT, Op::Add) => AddF { d, a, b },
        (Ty::FLOAT, Op::Sub) => SubF { d, a, b },
        (Ty::FLOAT, Op::Mul) => MulF { d, a, b },
        (Ty::FLOAT, Op::Div) => DivF { d, a, b },
        (Ty::FLOAT, Op::Rem) => RemF { d, a, b },
        (Ty::DOUBLE, Op::Add) => AddD { d, a, b },
        (Ty::DOUBLE, Op::Sub) => SubD { d, a, b },
        (Ty::DOUBLE, Op::Mul) => MulD { d, a, b },
        (Ty::DOUBLE, Op::Div) => DivD { d, a, b },
        (Ty::DOUBLE, Op::Rem) => RemD { d, a, b },
        (Ty::INT, Op::BwAnd) => Bits { op: BitOp::AndI, d, a, b },
        (Ty::INT, Op::BwOr) => Bits { op: BitOp::OrI, d, a, b },
        (Ty::INT, Op::Xor) => Bits { op: BitOp::XorI, d, a, b },
        (Ty::LONG, Op::BwAnd) => Bits { op: BitOp::AndL, d, a, b },
        (Ty::LONG, Op::BwOr) => Bits { op: BitOp::OrL, d, a, b },
        (Ty::LONG, Op::Xor) => Bits { op: BitOp::XorL, d, a, b },
        (Ty::BOOLEAN, Op::BwAnd) => Bits { op: BitOp::AndZ, d, a, b },
        (Ty::BOOLEAN, Op::BwOr) => Bits { op: BitOp::OrZ, d, a, b },
        (Ty::BOOLEAN, Op::Xor) => Bits { op: BitOp::XorZ, d, a, b },
        (Ty::INT, Op::Lsh) => Bits { op: BitOp::ShlI, d, a, b },
        (Ty::INT, Op::Rsh) => Bits { op: BitOp::ShrI, d, a, b },
        (Ty::INT, Op::Ush) => Bits { op: BitOp::UshrI, d, a, b },
        (Ty::LONG, Op::Lsh) => Bits { op: BitOp::ShlL, d, a, b },
        (Ty::LONG, Op::Rsh) => Bits { op: BitOp::ShrL, d, a, b },
        (Ty::LONG, Op::Ush) => Bits { op: BitOp::UshrL, d, a, b },
        _ => Mov { d, s: a },
    }
}

